recipes.code:
{
  "inputs": [
    {
      "id": "x402-private-key",
      "type": "promptString",
      "description": "EVM private key (64-char hex, 0x prefix optional) for automatic x402 USDC payments on Base",
      "password": true
    },
    {
      "id": "onesource-api-key",
      "type": "promptString",
      "description": "OneSource API key for Bearer token auth",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@one-source/mcp@5.9.1"
      ],
      "env": {
        "X402_PRIVATE_KEY": "${input:x402-private-key}",
        "ONESOURCE_API_KEY": "${input:onesource-api-key}"
      }
    }
  }
}
